<template>
  <div
    class="wml-login-main"
    :element-loading-text="loading.text"
    :element-loading-spinner="loading.spinner"
    :element-loading-background="loading.background"
    v-loading="loading.show"
  >
    <div style="-webkit-app-region:drag;">
      <i class="el-icon-close wml-login-closeicon no-drag" @click="closeWindows"></i>
      <div class="wml-login-logo" style>
        <img src="@/assets/image/logo.png" alt class="wml-login-logo-img" />
      </div>
      <div class="wml-login-input-box">
        <h2 :class="{'wml-login-en-tit':$i18n.locale === 'en'}">
          <!-- 全自动营销系统 -->
          {{ $t('login.systemName') }}
        </h2>
        <span>Welcome To My World</span>
        <el-form label-width="0" class="wml-login-form">
          <el-form-item class="no-drag">
            <!-- 请输入账号 -->
            <el-input
              v-model="form.UserAccount"
              size="medium"
              :placeholder="$t('login.usernameTip')"
              class="wml-login-input"
              @keyup.enter.native="doLogin"
            ></el-input>
          </el-form-item>
          <el-form-item class="no-drag">
            <!-- 请输入密码 -->
            <el-input
              size="medium"
              v-model="form.UserPassword"
              :placeholder="$t('login.passwordTip')"
              type="password"
              class="wml-login-input"
              @keyup.enter.native="doLogin"
            ></el-input>
          </el-form-item>
          <el-form-item class="MechanicalCode no-drag">
            <!-- 机器码 -->
            <el-input
              size="medium"
              v-model="form.MechanicalCode"
              :placeholder="$t('login.machineCode')"
              class="wml-login-input"
              disabled
            >
              <!-- 复制 -->
              <i
                slot="suffix"
                :title="$t('common.copyBtn')"
                class="el-icon-document-copy MechanicalCode-icon no-drag"
                @click="copyMechanicalCode"
              ></i>
            </el-input>
          </el-form-item>
        </el-form>
        <div class="login-box no-drag">
          <el-checkbox v-model="form.IsSave">
            <!-- 记住密码 -->
            {{ $t('login.remermberPaw') }}
          </el-checkbox>
          <button
            class="wml_login_submitbtn"
            :class="{'wml_login_submiten':$i18n.locale === 'en'}"
            @click="doLogin"
          >
            <!-- 登&nbsp;&nbsp;录 -->
            {{ $t('login.loginBtn') }}
          </button>
        </div>
      </div>
    </div>
    <upgrade :visible.sync="upgrade.show" :newVersionData="upgrade.versionData"></upgrade>
  </div>
</template>

<script>
import upgrade from '@/home/upgrade/index.vue'
import { mapActions } from 'vuex'
export default {
  name: 'login',
  components: { upgrade },
  data () {
    return {
      form: {
        UserAccount: '',
        UserPassword: '',
        MechanicalCode: '',
        IsSave: false
      },
      upgrade: {
        show: false,
        versionData: {
          vesion: '1.0.0.9',
          versionRemark: '',
          IsForceUpdate: false
        }
      },
      loading: {
        show: true,
        // '登录中'
        text: '检查更新中',
        spinner: 'el-icon-loading',
        background: 'rgba(255,255,255, .7)'
      }
    }
  },
  methods: {
    ...mapActions(['versionDispatch']),
    // test () {
    //   this.$i18n.locale = 'en'
    // },
    /**
     * @author: vince.Liang
     * @function: 关闭软件
     * @param {none}
     * @return:undefined
     */
    async closeWindows () {
      this.SharpObj.isCloseMainFrm(async res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        if (res.Data) {
          let confirm
          try {
            // 确定关闭程序吗？ 提示
            confirm = await this.$confirm(this.$t('common.closeTipBody'), this.$t('common.confirmTipTitle'), {
              // 确定
              confirmButtonText: this.$t('common.confirmButtonText'),
              // 取消
              cancelButtonText: this.$t('common.cancelButtonText'),
              type: 'warning',
              customClass: 'no-drag'
            })
          } catch (error) {
            confirm = error
          }
          if (confirm !== 'confirm') return
          Object.assign(this.loading, {
            // 关闭程序中
            text: this.$t('common.closingProgram'),
            spinner: 'el-icon-loading',
            background: 'rgba(255,255,255, .7)'
          })
          this.loading.show = true
          window.setTimeout(() => {
            this.SharpObj.closeForm()
          }, 600)
        } else {
          this.SharpObj.closeForm()
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 登陆
     * @param {none}
     * @return: undefined
     */
    doLogin () {
      let validate = this.$WmlValidator.validate([
        {
          value: this.form.UserAccount,
          rules: [
            {
              rule: 'isNonNull',
              // 请输入用户名
              errorMsg: this.$t('login.usernameTip')
            }
          ]
        },
        {
          value: this.form.UserPassword,
          rules: [
            {
              rule: 'isNonNull',
              // 请输入密码
              errorMsg: this.$t('login.passwordTip')
            }
          ]
        }
      ])
      if (validate) {
        this.$WmlMsg(validate, 'warning')
        return
      }
      Object.assign(this.loading, {
        // 登录中
        text: this.$t('login.logging'),
        spinner: 'el-icon-loading',
        background: 'rgba(255,255,255, .7)'
      })
      this.loading.show = true
      // 为了登陆
      // this.form.MechanicalCode = '3C6B9781BE4451945DF1C08F2C19E1D9'
      this.SharpObj.Login(JSON.stringify(this.form), res => {
        if (res.Code === 1) {
          this.SharpObj.SaveLoginData(JSON.stringify(this.form), res => {
            res = JSON.parse(res)
            if (res.Code === 0) {
              window.setTimeout(() => {
                this.loading.show = false
                // 登陆成功
                this.$WmlMsg(this.$t('login.loginSuccessTip'))
                this.$to({ path: 'home/index' })
              }, 1000)
            } else {
              window.setTimeout(() => {
                this.loading.show = false
                this.$WmlMsg(res.Msg, 'warning')
              }, 1000)
            }
          })
        } else {
          window.setTimeout(() => {
            this.loading.show = false
            this.$WmlMsg(res.Msg, 'warning')
          }, 1000)
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 初始化
     * @param {none}
     * @return: undefined
     */
    init () {
      this.SharpObj.getMechanicalCode(res => {
        res = JSON.parse(res)
        if (res.Code === 1) {
          this.form.MechanicalCode = res.Data
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
      this.SharpObj.GetLoginData(res => {
        res = JSON.parse(res)
        if (res.IsSave) {
          this.form.UserAccount = res.UserAccount
          this.form.UserPassword = res.UserPassword
          this.form.IsSave = res.IsSave
        }
      })
      this.SharpObj.getVersion(res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.versionDispatch(res.Data)
      })
    },

    /**
     * @author: vince.Liang
     * @function: 用户检查版本更新
     * @param {none}
     * @return: undefined
     */
    checkVersionUpdate () {
      this.loading.show = true
      this.SharpObj.getUpdateInfo(res => {
        this.loading.show = false
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        if (res.Data.IsForceUpdate || res.Data.IsShowUpdateNotice) {
          Object.assign(this.upgrade.versionData, res.Data)
          this.upgrade.show = true
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 复制
     * @param none
     * @return: return
     */
    copyMechanicalCode () {
      let input = document.createElement('input')
      input.value = this.form.MechanicalCode
      input.style.opacity = 0
      document.body.appendChild(input)
      input.select()
      document.execCommand('Copy')
      // 复制成功,快去粘贴吧!
      this.$WmlMsg(this.$t('common.copySuccessTip'))
      input.remove()
    }
  },
  created () {
    this.checkVersionUpdate()
    this.init()
  }
}

</script>

<style scoped>
.wml-login-closeicon {
  font-size: 28px;
  color: #fff;
  position: fixed;
  top: 5px;
  right: 10px;
  color: #fff;
  cursor: pointer;
  font-weight: 600;
}
.wml-login-closeicon:hover {
  color: red;
}
.wml-login-main {
  background-color: #fff;
  background: url("../../assets/image/login.jpg") no-repeat center;
  height: 100%;
  background-position: right;
  background-size: contain;
  text-align: initial;
}

.wml-login-form {
  width: 350px;
}
.wml-login-logo {
  padding: 50px 0 100px 50px;
}
.wml-login-logo-img {
  max-width: 230px;
}
.wml-login-input-box {
  padding-left: 120px;
}
.wml-login-input-box > h2 {
  /* color: #647bed; */
  color: #08a4ef;
  font-size: 46px;
  font-weight: 500;
  letter-spacing: 7px;
}

.wml-login-input-box > .wml-login-en-tit {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: 0px;
}

.wml-login-input-box > span {
  color: #25282e;
  font-weight: 500;
  display: inline-block;
  margin: 10px 0 30px;
  font-size: 20px;
}

.wml-login-input-box > label {
  display: block;
  width: 350px;
  height: 45px;
  border-radius: 40px;
  text-align: center;
  margin-bottom: 30px;
}
.wml-login-input >>> .el-input__inner {
  background-color: #f6f4fa;
  border: 0;
  border-radius: 30px;
  height: 45px;
}

.wml_login_submitbtn {
  /* background-color: #6888ef; */
  background-color: #08a4ef;
  border: 0;
  border-radius: 30px;
  color: #fff;
  padding: 10px 60px;
  box-shadow: 0px 10px 14px 0px #bccbfb;
  font-size: 18px;
  cursor: pointer;
}

.wml_login_submiten {
  padding: 10px 38px;
  font-size: 16px;
}

input::-webkit-input-placeholder {
  color: #bdbdbd;
}
input::-moz-input-placeholder {
  color: #bdbdbd;
}
input::-ms-input-placeholder {
  color: #bdbdbd;
}

.login-box {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 350px;
}

.login-box >>> .el-checkbox__input.is-checked .el-checkbox__inner,
.login-box >>> .el-checkbox__input.is-indeterminate .el-checkbox__inner {
  /* background-color: #5b65ef;
  border-color: #5b65ef; */
  background-color: #08a4ef;
  border-color: #08a4ef;
}
.login-box >>> .el-checkbox__inner:hover {
  /* border-color: #5b65ef; */
  border-color: #08a4ef;
}

.login-box >>> .is-checked .el-checkbox__label {
  /* color: #5b65ef; */
  color: #08a4ef;
}

.MechanicalCode >>> .el-form-item__content {
  display: flex;
  align-items: center;
}

.MechanicalCode .MechanicalCode-icon {
  font-size: 23px;
  margin-right: 10px;
  cursor: pointer;
}

.MechanicalCode >>> .el-input__suffix-inner {
  height: 100%;
  display: flex;
  align-items: center;
}

.MechanicalCode .MechanicalCode-icon {
  /* color: #6888ef; */
  color: #08a4ef;
}

.wml-login-main >>> .el-loading-spinner i {
  font-size: 30px;
  font-weight: 700;
  /* color: #6888ef; */
  color: #08a4ef;
}

.wml-login-main >>> .el-loading-text {
  font-size: 20px;
  /* color: #6888ef; */
  color: #08a4ef;
}
</style>
